from fastapi.sse import ServerSentEvent

def test_sse_validation():
    # Test ID validation
    try:
        ServerSentEvent(id="valid-id")
        print("ID valid test passed.")
    except Exception as e:
        print(f"ID valid test failed unexpectedly: {e}")

    try:
        ServerSentEvent(id="id_with_newline\n")
        print("ID newline test failed: did not raise error.")
    except ValueError as e:
        print(f"ID newline test passed: {e}")
    except Exception as e:
        print(f"ID newline test failed with wrong exception: {e}")

    try:
        ServerSentEvent(id="id_with_null\0")
        print("ID null test failed: did not raise error.")
    except ValueError as e:
        print(f"ID null test passed: {e}")
    except Exception as e:
        print(f"ID null test failed with wrong exception: {e}")

    # Test Event validation
    try:
        ServerSentEvent(event="valid-event")
        print("Event valid test passed.")
    except Exception as e:
        print(f"Event valid test failed unexpectedly: {e}")

    try:
        ServerSentEvent(event="event_with_newline\n")
        print("Event newline test failed: did not raise error.")
    except ValueError as e:
        print(f"Event newline test passed: {e}")
    except Exception as e:
        print(f"Event newline test failed with wrong exception: {e}")

test_sse_validation()
PY
